package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Move a claim along its status: open, settle, approve, reject (with a reason) or void, each only from the
 *  statuses it allows; or defer an OPEN claim until a date (see {@link ClaimDeferral}); or raise its proofs count (see {@link ClaimProof}); or split an amount off an OPEN claim (see {@link ClaimSplit}); or part-settle one (see {@link ClaimSettlePart}); or re-date an OPEN or PENDING claim (see {@link ClaimRedate}); or lock or unlock a claim's editor (see {@link ClaimLock}); or remind an OPEN or PENDING claim (see {@link ClaimRemind}); or comment a claim (see {@link ClaimComment}); or delete a DRAFT claim or restore it the same day (see {@link ClaimDelete}); or add a line to a DRAFT claim (see {@link ClaimLine}); or waive an OPEN or PENDING claim's late charge (see {@link ClaimWaive}); or hold or release an OPEN or PENDING claim (see {@link ClaimHold}). */
public class ChangeClaimStatus {
    public void change(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            @PathVariable("action") String action, @RequestBody ClaimActionRequest request, ServerHttpConnection connection, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, SheetRepository sheets, Audit audit, Rollup rollup, WatchRepository watches, PersonRepository people, AsOfView view, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        if ("defer".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimDeferral.apply(id, cid, request == null ? null : request.until(), by, repository, sheets,
                    periods, audit, rollup));
            return;
        }
        if ("split".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimSplit.apply(id, cid, request == null ? null : request.amount(), by, repository, periods,
                    settings, audit, rollup));
            return;
        }
        if ("settle-part".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimSettlePart.apply(id, cid, request == null ? null : request.amount(), by, repository, periods,
                    settings, audit, rollup, watches));
            return;
        }
        if ("redate".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimRedate.apply(id, cid, request == null ? null : request.date(), by, repository, periods,
                    settings, people, audit, rollup));
            return;
        }
        if ("lock".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimLock.lock(id, cid, by, repository, periods));
            return;
        }
        if ("unlock".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimLock.unlock(id, cid, by, repository));
            return;
        }
        if ("remind".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimRemind.apply(id, cid, by, repository, audit));
            return;
        }
        if ("comment".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimComment.apply(id, cid, request == null ? null : request.text(), by, repository, audit));
            return;
        }
        if ("delete".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimDelete.delete(id, cid, by, repository, periods, settings, audit));
            return;
        }
        if ("restore".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimDelete.restore(id, cid, by, repository, periods, settings, audit));
            return;
        }
        if ("line".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimLine.apply(id, cid, request == null ? null : request.label(), request == null ? null : request.qty(),
                    request == null ? null : request.unit(), by, repository, periods, settings, audit));
            return;
        }
        if ("waive".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimWaive.apply(id, cid, by, repository, settings, audit, rollup));
            return;
        }
        if ("hold".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimHold.toggle(id, cid, by, repository, settings, audit, rollup));
            return;
        }
        if ("proof".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimProof.apply(id, cid, request == null ? null : request.kind(), by, repository, periods, audit));
            return;
        }
        if ("settle".equals(action == null ? "" : action.trim())) {
            claim.set(ClaimStatusChange.settle(id, cid, request == null ? null : request.on(), by, view, repository, periods,
                    settings, audit, rollup, watches));
            return;
        }
        claim.set(ClaimStatusChange.apply(id, cid, action,
                request == null ? null : request.reason(), by, repository, periods, settings, audit, rollup, watches));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** Hold an OPEN or PENDING claim, or release it when it is held: a held claim still counts in every total (a hold
 *  acts only on pool cuts, and only a person's). A claim in any other status is
 *  refused. Every check is made before anything is written, so a refusal writes nothing to the store or the audit. */
final class ClaimHold {
    private ClaimHold() {
    }

    static Claim toggle(String id, long cid, String by, ClaimRepository repository, SettingsRepository settings,
            Audit audit, Rollup rollup) throws BadRequestException {
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.open()) {
            throw new BadRequestException("a " + found.status() + " claim cannot be held or released");
        }
        boolean hold = !found.held();
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.hold(id, cid, hold)) {
            throw new BadRequestException("the claim cannot be " + (hold ? "held" : "released"));
        }
        audit.record((hold ? "CLAIM_HELD" : "CLAIM_RELEASED") + " sheet=" + id + " by=" + by + " person="
                + repository.personName(id, found.personId()) + " amount=" + found.amount() + " date=" + found.date()
                + Claim.auditNumber(found.number()));
        rollup.record(id, by, before);
        return repository.find(id, cid);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
 *  line per person whose figures moved (people in list order; a new person counts as
 *  moved), then a TOTALS line when the sheet's totals moved, then, while the sheet has an alert threshold, one ALERT
 *  line per person (in list order) whose due-total went from at or below it (or none) to above it. */
@Service
public class Rollup {

    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none), and
     *  score (the sum of the dues now of their counting SETTLED claims that correct nothing divided by 100, rounded half to even to a whole
     *  number, minus 5 for every counting claim of theirs that is overdue). */
    record Figures(String name, String claimed, String dueTotal, String overdueTotal, long score) {
        boolean same(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The figures of a sheet at one moment, people by id in list order. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;
    private final SettingsRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
            Audit audit) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now. A person's claimed is the sum of their counting claims' amounts, leaving out corrections
     *  (claims that correct another). A person's due-total is the sum of their counting claims' dues now (late charges included),
     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'.
     *  The sheet's due-total and overdue-total leave out the single highest and lowest person's figure when three or more
     *  people have one. */
    public Snapshot take(String sheetId) {
        List<Person> everyone = people.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        if (!everyone.isEmpty()) {
            LocalDate today = sheets.today(sheetId);
            List<Claim> all = claims.list(sheetId);
            BigDecimal cap = settings.cap(sheetId);
            for (Person p : everyone) {
                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
                BigDecimal due = BigDecimal.ZERO.setScale(2);
                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
                BigDecimal settled = BigDecimal.ZERO.setScale(2);
                int overdueCount = 0;
                boolean fixed = false;
                for (Claim c : all) {
                    if (c.personId() != p.id()) continue;
                    String on = today == null ? null : today.toString();
                    if (c.corrects() == null && c.countsClaimed(p.claimedHolds(on))) claimed = claimed.add(new BigDecimal(c.amount()));
                    if (!c.counts(p.liveHolds(on))) continue;
                    fixed |= c.fixed();
                    BigDecimal now = claims.dueNow(sheetId, c);
                    if (now != null) due = due.add(now);
                    if (now != null && claims.overdue(sheetId, c, today)) overdue = overdue.add(now);
                    if (now != null && "SETTLED".equals(c.status()) && c.corrects() == null) settled = settled.add(now);
                    if (claims.overdue(sheetId, c, today)) overdueCount++;
                    fixed |= now != null;
                }
                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
                due = SettingsRepository.capped(due, cap);
                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
                        shown ? due.toPlainString() : "n/a", overdue.toPlainString(),
                        settled.movePointLeft(2).setScale(0, RoundingMode.HALF_EVEN).longValueExact() - 5L * overdueCount));
                claimedTotal = claimedTotal.add(claimed);
                if (shown) dues.add(due);
                overdues.add(overdue);
            }
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
                trimmed(overdues).toPlainString());
    }

    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        Collections.sort(sorted);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (BigDecimal f : sorted) total = total.add(f);
        return total;
    }

    /** Record one SNAPSHOT line per person (in list order) with their due-total as {@code before} had it,
     *  ending with for=<steward> when {@code by} made the change under that steward's delegation (null when not),
     *  and keep it on the person with the day being left. */
    public void snapshot(String sheetId, String by, Snapshot before, String delegator, LocalDate dayLeft) {
        for (Map.Entry<Long, Figures> e : before.people().entrySet()) {
            Figures f = e.getValue();
            people.snapshot(sheetId, e.getKey(), dayLeft, f.dueTotal());
            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total=" + f.dueTotal()
                    + (delegator == null ? "" : " for=" + delegator));
        }
    }

    /** Record one SCORE line per person (in list order) with their score as {@code before} had it. */
    public void scores(String sheetId, String by, Snapshot before) {
        for (Figures f : before.people().values()) {
            audit.record("SCORE sheet=" + sheetId + " by=" + by + " name=" + f.name() + " score=" + f.score());
        }
    }

    /** Record the lines for every person (in list order) and the sheet's totals, moved or not. */
    public void recordAll(String sheetId, String by) {
        Map<Long, Figures> none = Map.of();
        record(sheetId, by, new Snapshot(none, "", "", ""));
    }

    /** Record the lines for whatever figures moved since {@code before}. */
    public void record(String sheetId, String by, Snapshot before) {
        Snapshot after = take(sheetId);
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.same(before.people().get(e.getKey()))) continue;
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) return;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            Figures was = before.people().get(e.getKey());
            if (above(now, threshold) && !above(was, threshold)) {
                audit.record("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total=" + now.dueTotal());
            }
        }
    }

    /** Whether a person's due-total is above the threshold (no figures, or an 'n/a', is not). */
    private static boolean above(Figures f, BigDecimal threshold) {
        return f != null && !"n/a".equals(f.dueTotal()) && new BigDecimal(f.dueTotal()).compareTo(threshold) > 0;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.person.Hold;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED, VOID or DELETED — a deleted DRAFT, counted nowhere), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; given when it is settled or approved, so null while DRAFT, REVIEW, OPEN or PENDING, unless numbered on opening before; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
 *  created, its date then plus its person's own terms, else the terms of their grade on that date, else the sheet's terms), and
 *  whether its last statement bound it to n/a (the rate that would apply to it had ended: its due then
 *  stays n/a, not live), and the date it is deferred until (null when never deferred) and whether it is
 *  deferred now (OPEN and that date after the sheet's today: it then counts in no total, is not overdue,
 *  cannot be settled and a statement leaves it unbound), and how many proofs it has been given, and, for a claim
 *  split off another, the number of the claim it was split from (null otherwise), and whether it was a late entry
 *  (added while the period its due-by falls in was soft-closed), and the last day (the sheet's today then) a reminder
 *  was written for it (null when never reminded), and its external reference (null when none), and its tags (lower-case, sorted and
 *  comma separated, with no spaces; null when none), and the reason it was voided with (one of its sheet's void reasons; null when none was given), and whether a steward
 *  waived its late charge (it then bears none, whatever its overdue state), and how many of its proofs are photos (the
 *  rest are receipts), and whether it is held (an OPEN or PENDING claim held on its own: it still counts in every
 *  total). */
public record Claim(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String dueBy, boolean statedNa, String deferredUntil, boolean deferred, int proofs, String splitFrom,
        boolean lateEntry, String reminded, String ref, String tags, String voidReason, boolean waived, int photos, boolean held) {

    /** The kinds a proof can be, the first (receipt) being a proof's kind when none is chosen. */
    public static final List<String> PROOF_KINDS = List.of("receipt", "photo");

    /** How many of its proofs are of a kind (receipt or photo). */
    public int proofs(String kind) {
        return kind.equals("photo") ? photos : proofs - photos;
    }

    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere). */
    public boolean open() {
        return status.equals("OPEN") || status.equals("PENDING");
    }

    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
    public boolean counts() {
        return open() || status.equals("SETTLED");
    }

    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given the holds that
     *  take its person's claims out (only their retirement's: see Person#liveHolds): an open claim dated within one does
     *  not, unless a statement binds it; SETTLED claims always do. A deferred claim does not. A hold of its own or of its
     *  person's no longer takes it out (a hold acts only on pool cuts). */
    public boolean counts(List<Hold> holds) {
        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
    }

    /** Whether the claim counts toward claimed: as {@link #counts(List)}, except that a hold (its own or one of its
     *  person's) does not take it out; given only the holds that do (see Person#claimedHolds). */
    public boolean countsClaimed(List<Hold> holds) {
        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
    }

    /** Whether the claim counts toward a period ending on a day, given the status it had at the end of that
     *  day (null when it did not exist then: it does not count) and its person's holds: the live rules
     *  applied to that status (an open claim deferred until after the sheet's today does not count either). A hold
     *  leaves out only a claim still open now: one since settled or voided counts by the status it had then. */
    public boolean countsAs(String statusThen, List<Hold> holds, String today) {
        if (statusThen == null) return false;
        boolean deferredNow = statusThen.equals("OPEN") && deferredUntil != null && today != null && today.compareTo(deferredUntil) < 0;
        Claim then = new Claim(id, personId, amount, date, note, statusThen, number, due, openedBy, stated, statedDue,
                corrects, dueBy, statedNa, deferredUntil, deferredNow, proofs, splitFrom, lateEntry, reminded, ref, tags, voidReason, waived, photos, held && open());
        return then.counts(open() ? holds : List.of());
    }

    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it to. */
    public boolean fixed() {
        return due != null || (bound() && statedDue != null);
    }

    /** Whether its last statement binds it now: it was stated (a PENDING claim is bound like any other). */
    public boolean bound() {
        return stated;
    }

    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
    static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }

    /** The audit field a claim with an external reference adds at the end of CLAIM_ADDED: " ref=<reference>", or "" when it has none. */
    public static String auditRef(String ref) {
        return ref == null ? "" : " ref=" + ref;
    }

    /** The audit field a claim with tags adds at the end of CLAIM_ADDED: " tags=<comma separated, sorted>", or "" when it has none. */
    public static String auditTags(String tags) {
        return tags == null ? "" : " tags=" + tags;
    }

    /** Typed tags as a claim keeps them: split on commas, each trimmed and lower-cased, blanks and repeats
     *  dropped, sorted and joined with commas; null when none is left. */
    public static String tags(String typed) {
        if (typed == null) return null;
        java.util.TreeSet<String> set = new java.util.TreeSet<>();
        for (String t : typed.split(",")) {
            String tag = t.trim().toLowerCase(java.util.Locale.ROOT);
            if (!tag.isEmpty()) set.add(tag);
        }
        return set.isEmpty() ? null : String.join(",", set);
    }
}

